ALTER TABLE public.bridge_site_content
  ADD COLUMN IF NOT EXISTS carousel_slides jsonb NOT NULL DEFAULT '[]'::jsonb;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'bridge_site_content_carousel_slides_array_check'
      AND conrelid = 'public.bridge_site_content'::regclass
  ) THEN
    ALTER TABLE public.bridge_site_content
      ADD CONSTRAINT bridge_site_content_carousel_slides_array_check
      CHECK (jsonb_typeof(carousel_slides) = 'array' AND jsonb_array_length(carousel_slides) <= 5);
  END IF;
END $$;
COMMENT ON COLUMN public.bridge_site_content.carousel_slides IS
  'Up to five public homepage carousel slides; each item stores an HTTPS image URL, alt text and caption.';

CREATE TABLE IF NOT EXISTS public.bridge_legal_acceptances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  bridge_user_id text NOT NULL REFERENCES public.bridge_profiles(user_id) ON DELETE RESTRICT,
  auth_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  terms_version text NOT NULL,
  privacy_version text NOT NULL,
  client_acknowledged_at timestamptz,
  accepted_at timestamptz NOT NULL DEFAULT now(),
  source text NOT NULL DEFAULT 'signup',
  CONSTRAINT bridge_legal_acceptances_source_check CHECK (source IN ('signup', 'account_update')),
  CONSTRAINT bridge_legal_acceptances_versions_check CHECK (
    length(terms_version) BETWEEN 1 AND 40 AND length(privacy_version) BETWEEN 1 AND 40
  ),
  CONSTRAINT bridge_legal_acceptances_user_versions_unique UNIQUE (bridge_user_id, terms_version, privacy_version)
);
CREATE INDEX IF NOT EXISTS bridge_legal_acceptances_auth_user_idx
  ON public.bridge_legal_acceptances(auth_user_id, accepted_at DESC);
ALTER TABLE public.bridge_legal_acceptances ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.bridge_legal_acceptances FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.bridge_legal_acceptances TO postgres, service_role;
COMMENT ON TABLE public.bridge_legal_acceptances IS
  'Private server-recorded acknowledgement of versioned Crayons Bridge B2B legal policies.';

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['bridge_conditional_submissions','bridge_creator_documents','bridge_dit_copy_verifications','bridge_dit_ingest_files','bridge_dit_ingest_sessions','bridge_dit_storage_objects','bridge_legal_acceptances','bridge_owner_submission_events','bridge_production_schedule_events','bridge_rights_evidence','bridge_rights_evidence_reviews','bridge_settlement_reference_claim_events','bridge_settlement_reference_claims','bridge_site_content','bridge_studio_invites','bridge_studio_ownership_transfers','bridge_sublicense_authorizations','bridge_title_archive_events','bridge_title_control_events','bridge_title_controls','bridge_title_document_links','bridge_title_owner_submissions','streamvista_legacy_links','streamvista_project_assets','streamvista_projects','streamvista_service_orders']::text[] LOOP
    IF to_regclass(format('public.%I', t)) IS NULL THEN
      RAISE EXCEPTION 'Expected STAGING table public.% missing', t;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c
      WHERE c.oid = to_regclass(format('public.%I', t))
        AND c.relrowsecurity
    ) THEN
      RAISE EXCEPTION 'RLS is not enabled on public.%', t;
    END IF;
    IF EXISTS (
      SELECT 1 FROM pg_policies p
      WHERE p.schemaname='public' AND p.tablename=t
    ) THEN
      RAISE EXCEPTION 'Existing policy found on public.%; refusing to overwrite policy model', t;
    END IF;
    EXECUTE format(
      'CREATE POLICY deny_browser_access ON public.%I FOR ALL TO anon, authenticated USING (false) WITH CHECK (false)',
      t
    );
  END LOOP;
END $$;

