CREATE TABLE public.bridge_service_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  requester_user_id text NOT NULL REFERENCES public.bridge_profiles(user_id) ON DELETE RESTRICT,
  requester_account_type text NOT NULL CHECK (requester_account_type IN ('independent_creator','studio')),
  organization_id uuid REFERENCES public.bridge_organizations(id) ON DELETE RESTRICT,
  title_id text NOT NULL REFERENCES public.bridge_titles(id) ON DELETE RESTRICT,
  category text NOT NULL CHECK (length(category) BETWEEN 2 AND 100),
  description text NOT NULL CHECK (length(description) BETWEEN 10 AND 4000),
  attachment_document_ids text[] NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED','UNDER_REVIEW','QUOTE_READY','AWAITING_PAYMENT','PAID','ASSIGNED','IN_PROGRESS','REVIEW','COMPLETED','CANCELLED','REFUNDED')),
  quote_id uuid REFERENCES public.bridge_service_quotes(id) ON DELETE RESTRICT,
  order_id uuid REFERENCES public.bridge_service_orders(id) ON DELETE RESTRICT,
  assigned_provider text,
  delivery_evidence_url text CHECK (delivery_evidence_url IS NULL OR delivery_evidence_url LIKE 'https://%'),
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT bridge_service_requests_account_scope CHECK (
    (requester_account_type='independent_creator' AND organization_id IS NULL)
    OR (requester_account_type='studio' AND organization_id IS NOT NULL)
  )
);
CREATE INDEX bridge_service_requests_owner_idx ON public.bridge_service_requests(requester_user_id,created_at DESC);
CREATE INDEX bridge_service_requests_org_idx ON public.bridge_service_requests(organization_id,created_at DESC) WHERE organization_id IS NOT NULL;
CREATE INDEX bridge_service_requests_status_idx ON public.bridge_service_requests(status,created_at DESC);
CREATE UNIQUE INDEX bridge_service_requests_quote_uq ON public.bridge_service_requests(quote_id) WHERE quote_id IS NOT NULL;
CREATE UNIQUE INDEX bridge_service_requests_order_uq ON public.bridge_service_requests(order_id) WHERE order_id IS NOT NULL;

CREATE TABLE public.bridge_service_request_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id uuid NOT NULL REFERENCES public.bridge_service_requests(id) ON DELETE RESTRICT,
  from_status text,
  to_status text NOT NULL,
  actor_user_id text,
  note text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX bridge_service_request_events_request_idx ON public.bridge_service_request_events(request_id,created_at DESC);

CREATE TABLE public.bridge_service_request_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id uuid NOT NULL REFERENCES public.bridge_service_requests(id) ON DELETE RESTRICT,
  recipient_user_id text,
  organization_id uuid REFERENCES public.bridge_organizations(id) ON DELETE RESTRICT,
  title text NOT NULL,
  message text NOT NULL,
  read_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT bridge_service_request_notification_recipient CHECK (recipient_user_id IS NOT NULL OR organization_id IS NOT NULL)
);
CREATE INDEX bridge_service_request_notifications_user_idx ON public.bridge_service_request_notifications(recipient_user_id,created_at DESC) WHERE recipient_user_id IS NOT NULL;
CREATE INDEX bridge_service_request_notifications_org_idx ON public.bridge_service_request_notifications(organization_id,created_at DESC) WHERE organization_id IS NOT NULL;

